","new_string":"import { revalidateTag } from 'next/cache'
import { getProducts } from '../lib/products'

export default async function Page() {
  const products = await getProducts()

  async function syncCatalog() {
    'use server'
    revalidateTag('products', 'max')
  }

  return (
    <main>
      <h1>Product catalog</h1>
      <form action={syncCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>
      <p>Catalog updates may take a moment to appear after syncing.</p>
      <table>
        <thead>
          <tr>
            <th scope="col">Product</th>
            <th scope="col">Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id}>
              <td>{product.name}</td>
              <td>{new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(product.price)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}
"}

